const CONFIG = {
  STATE_DIR: '/data/buchhaltung/_regulatorik',      // Zustand, Wochen-Warteschlange, Berichte
  OLLAMA_URL: 'http://host.docker.internal:11434/api/chat',
  MODELL: 'mistral',
};
// Nur öffentliche Seiten. typ: rss = Feed, seite = Seitenvergleich. filter = nur Treffer mit diesen Wörtern melden (null = alles).
const KI = '(\\bKI\\b|künstliche[nr]? Intelligenz|KI-VO|KI-Verordnung|AI Act|\\bAI\\b|artificial intelligence|AI Office|Sprachmodell|Algorithm|automatisierte Entscheidung)';
const QUELLEN = [
  { id: 'eurlex-kivo', name: 'EUR-Lex · KI-Verordnung 2024/1689 (Fassungen)', typ: 'seite', sprache: 'de',
    url: 'https://eur-lex.europa.eu/legal-content/DE/ALL/?uri=CELEX:32024R1689', filter: null, aktiv: false }, // blockt per AWS-WAF (JavaScript-Prüfung) – nicht umgehen; Technik-Tag: Cellar-SPARQL der EU-Publikationsamts prüfen
