return QUELLEN.filter(q => q.aktiv !== false).map(q => ({ json: { ...q, ...CONFIG } }));

// Erkennt neue Einträge (RSS) und neue Textzeilen (Seiten). Erster Lauf je Quelle = Ausgangsstand, keine Meldung.
const fs = require('fs'); const path = require('path');
const quellen = $('Quellen').all().map(x => x.json);
const antworten = $input.all().map(x => x.json);
const DIR = quellen[0].STATE_DIR;
fs.mkdirSync(DIR, { recursive: true });
const SF = path.join(DIR, 'zustand.json');
let state = {}; try { state = JSON.parse(fs.readFileSync(SF, 'utf8')); } catch (e) { state = {}; }
const heute = new Date().toISOString().slice(0, 10);

function fnv(s) { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return h.toString(16); }
function ent(s) { return String(s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)); }
function ohneTags(s) { const u = String(s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1'); return ent(ent(u).replace(/<[^>]+>/g, ' ').replace(/<[^>]+>/g, ' ')).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(); }
function zeilen(html) {
  let t = String(html || '').replace(/<(script|style|noscript|nav|header|footer|svg|form)[\s\S]*?<\/\1>/gi, ' ');
  t = t.replace(/<(br|\/p|\/div|\/li|\/h\d|\/tr|\/td)[^>]*>/gi, '\n');
  return [...new Set(ohneTags(t.replace(/\n/g, '§§')).split('§§').map(z => z.replace(/\s+/g, ' ').trim()).filter(z => z.length >= 20))];
}
function rss(xml) {
  const out = [];
  for (const m of String(xml || '').matchAll(/<(item|entry)\b[\s\S]*?<\/\1>/gi)) {
    const b = m[0];
    const g = re => { const r = b.match(re); return r ? ohneTags(r[1]) : ''; };
    let link = g(/<link>([\s\S]*?)<\/link>/i); if (!link) { const r = b.match(/<link[^>]*href="([^"]+)"/i); link = r ? r[1] : ''; }
    out.push({ titel: g(/<title[^>]*>([\s\S]*?)<\/title>/i), link: link.trim(), datum: g(/<(?:pubDate|updated|dc:date)>([\s\S]*?)<\/(?:pubDate|updated|dc:date)>/i),
      text: g(/<(?:description|summary|content)[^>]*>([\s\S]*?)<\/(?:description|summary|content)>/i) });
  }
  return out;
}

const events = [];
quellen.forEach((q, i) => {
  const a = antworten[i] || {};
  const body = typeof a.body === 'string' ? a.body : (typeof a.data === 'string' ? a.data : '');
  const st = state[q.id] || { fehler: 0 };
  const blockiert = /awswaf|challenge\.js|enable javascript|captcha|access denied|request rejected/i.test(body.slice(0, 5000)) || (q.typ === 'seite' && zeilen(body).length < 3) || (q.typ === 'rss' && !/<(item|entry)\b/i.test(body));
  if (!body || a.error || blockiert) {
    st.fehler = (st.fehler || 0) + 1;
    if (st.fehler === 3) events.push({ quelle: q.name, quelle_id: q.id, titel: blockiert ? 'Quelle blockt automatische Abrufe (seit 3 Läufen)' : 'Quelle seit 3 Läufen nicht erreichbar', link: q.url, datum: heute, text: '', ki: false,
      ergebnis: { neu: 'Die Quelle war dreimal hintereinander nicht abrufbar.', betroffen: '–', frist: null, relevanz: 'mittel', handlung: 'Adresse im Browser prüfen und in der Quellenliste anpassen.' }, hinweise: [blockiert ? 'Seite verlangt JavaScript/Captcha – nicht umgehen, andere Quelle oder offizielle Schnittstelle nutzen' : 'Abruffehler'] });
    state[q.id] = st; return;
  }
  st.fehler = 0;
  const filt = q.filter ? new RegExp(q.filter, 'i') : null;
  const erster = !st.init;
  if (q.typ === 'rss') {
    const items = rss(body);
    const gesehen = new Set(st.gesehen || []);
    for (const it of items) {
      const key = it.link || fnv(it.titel);
      if (gesehen.has(key)) continue;
      gesehen.add(key);
      if (erster) continue;
      if (filt && !filt.test(it.titel + ' ' + it.text)) continue;
      events.push({ quelle: q.name, quelle_id: q.id, titel: it.titel, link: it.link || q.url, datum: it.datum || heute, text: (it.titel + '\n' + it.text).slice(0, 6000), ki: true });
    }
    st.gesehen = [...gesehen].slice(-400);
  } else {
    const neu = zeilen(body);
    const alt = new Set(st.zeilen || []);
    const h = fnv(neu.join('\n'));
    if (!erster && h !== st.hash) {
      let dazu = neu.filter(z => !alt.has(z));
      if (filt) dazu = dazu.filter(z => filt.test(z));
      const txt = dazu.join('\n');
      if (txt.length >= 40) events.push({ quelle: q.name, quelle_id: q.id, titel: dazu[0].slice(0, 160), link: q.url, datum: heute, text: txt.slice(0, 6000), ki: true });
    }
    st.hash = h; st.zeilen = neu.slice(0, 3000);
  }
  st.init = true; st.letzterAbruf = heute;
  state[q.id] = st;
});
fs.writeFileSync(SF, JSON.stringify(state));
const c = quellen[0];
return events.map(e => ({ json: { ...e, OLLAMA_URL: c.OLLAMA_URL, MODELL: c.MODELL, STATE_DIR: c.STATE_DIR, test: false } }));

