  html += `<h3>${icon[r.relevanz] || '•'} ${esc(e.titel)}</h3><p style="color:#6B7A90">${esc(e.quelle)} · ${esc(e.datum)}</p><p>${esc(r.neu)}</p><ul><li><b>Betroffen:</b> ${esc(r.betroffen)}</li><li><b>Frist:</b> ${esc(r.frist || '–')}</li><li><b>Tun:</b> ${esc(r.handlung)}</li>${(e.hinweise || []).map(h => '<li>' + esc(h) + '</li>').join('')}</ul><p><a href="${esc(e.link)}">Quelle öffnen</a></p>`;
}
md += '\n---\nKI-Zusammenfassungen (lokales Modell). Vor jeder Verwendung gegen die Quelle prüfen. Fristen nur aus dem Gesetzestext (EUR-Lex, konsolidierte Fassung).\n';
html += '<hr><p style="font-size:12px;color:#6B7A90">KI-Zusammenfassungen (lokales Modell). Vor jeder Verwendung gegen die Quelle prüfen. Fristen nur aus dem Gesetzestext.</p>';
