fs.writeFileSync(QF, '[]');
return [{ json: { betreff: `Regulatorik-Monitor KW ${kw}: ${q.filter(e => e.ergebnis?.relevanz === 'hoch').length} wichtig, ${q.length} gesamt`, html, datei, anzahl: q.length } }];

